#!/usr/bin/python3
"""Tests for honey-heartbeat (generated by agents-bots-honey.org). No root, no network, no OpenRC: the fixtures are real processes.
HONEY_HEARTBEAT=/path overrides the program under test (the mutation proof uses it)."""
import importlib.machinery, importlib.util, json, os, re, signal, subprocess, sys, tempfile, time, unittest

HERE = os.path.dirname(os.path.abspath(__file__))
PROG = next(os.path.abspath(c) for c in (os.environ.get('HONEY_HEARTBEAT', ''), os.path.join(HERE, '..', '..', '..', 'bin', 'honey-heartbeat'), os.path.join(HERE, 'honey-heartbeat')) if c and os.path.isfile(c))
_spec = importlib.util.spec_from_loader('hb', importlib.machinery.SourceFileLoader('hb', PROG))
hb = importlib.util.module_from_spec(_spec); _spec.loader.exec_module(hb)


def rd(p):
    with open(p) as fh:
        return fh.read()


class Fixture(unittest.TestCase):
    """A scratch heartbeat dir and real processes: LIVE (sleeping), DEAD (exited and reaped), ZOMBIE (exited, not reaped)."""
    def setUp(self):
        self.d = tempfile.mkdtemp(prefix='hb-')
        self.kids = []
        self.addCleanup(self.cleanup)

    def cleanup(self):
        for k in self.kids:
            if k.poll() is None:
                k.kill()
            try: k.wait(5)
            except Exception: pass
        subprocess.run(['rm', '-rf', self.d])

    def live(self):
        k = subprocess.Popen(['sleep', '300']); self.kids.append(k); return k.pid

    def dead(self):
        k = subprocess.Popen(['true']); k.wait(); return k.pid

    def zombie(self):
        k = subprocess.Popen(['true']); self.kids.append(k)
        for _ in range(100):
            try:
                if rd('/proc/%d/stat' % k.pid).rsplit(')', 1)[1].split()[0] == 'Z': return k.pid
            except OSError: pass
            time.sleep(0.02)
        self.fail('no zombie')

    def pidfile(self, name, pid):
        p = os.path.join(self.d, name + '.pid')
        with open(p, 'w') as fh: fh.write('%d\n' % pid)
        return p

    def beat(self, name, pid, age=0, status='ok', detail=''):
        return hb.write_beat(self.d, name, pid, status, detail, now=time.time() - age)

    def cli(self, *args):
        p = subprocess.run([sys.executable, '-I', PROG, *args, '--dir', self.d], capture_output=True, text=True, timeout=30)
        return p.returncode, p.stdout.strip(), p.stderr.strip()

    def chk(self, name, pidfile, max_age=60):
        return self.cli('check', name, '--pidfile', pidfile, '--max-age', str(max_age))


class TheTwoFixtures(Fixture):
    """The unit's acceptance: a service that is DEAD and one that is ALIVE BUT SILENT are reported differently."""
    def build(self):
        # DEAD: its process exited (reaped), and it last beat 10 minutes ago.
        dpid = self.dead(); dpf = self.pidfile('deadsvc', dpid); self.beat('deadsvc', dpid, age=600)
        # ALIVE BUT SILENT: its process is running, and it last beat 10 minutes ago too (identical heartbeat evidence).
        lpid = self.live(); lpf = self.pidfile('silentsvc', lpid); self.beat('silentsvc', lpid, age=600)
        return dpf, lpf

    def test_dead_and_alive_but_silent_never_produce_the_same_output(self):
        dpf, lpf = self.build()
        drc, dout, _ = self.chk('deadsvc', dpf); lrc, lout, _ = self.chk('silentsvc', lpf)
        self.assertNotEqual(drc, lrc, 'same exit status for DEAD and SILENT')
        self.assertNotEqual(dout.split()[0], lout.split()[0], 'same state word for DEAD and SILENT')
        self.assertNotEqual(dout.replace('deadsvc', 'X').replace(str(drc), ''), lout.replace('silentsvc', 'X').replace(str(lrc), ''))
        self.assertEqual((dout.split()[0], drc), ('DEAD', 3)); self.assertEqual((lout.split()[0], lrc), ('NO-HEARTBEAT', 2))

    def test_even_with_NO_heartbeat_at_all_the_two_cases_differ(self):
        dpid = self.dead(); dpf = self.pidfile('deadsvc', dpid)
        lpf = self.pidfile('silentsvc', self.live())
        drc, dout, _ = self.chk('deadsvc', dpf); lrc, lout, _ = self.chk('silentsvc', lpf)
        self.assertEqual((dout.split()[0], lout.split()[0]), ('DEAD', 'NO-HEARTBEAT')); self.assertNotEqual(drc, lrc)

    def test_the_reasons_say_what_is_true_in_each_case(self):
        dpf, lpf = self.build()
        _, dout, _ = self.chk('deadsvc', dpf); _, lout, _ = self.chk('silentsvc', lpf)
        self.assertIn('process=dead', dout); self.assertIn('last heartbeat 600s ago', dout)
        self.assertIn('process=alive', lout); self.assertIn('last heartbeat is 600s old (threshold 60s)', lout)

    def test_dead_and_silent_are_both_distinct_from_healthy_and_unhealthy(self):
        dpf, lpf = self.build()
        hpid = self.live(); hpf = self.pidfile('okay', hpid); self.beat('okay', hpid)
        upid = self.live(); upf = self.pidfile('sick', upid); self.beat('sick', upid, status='failing', detail='db gone')
        got = {n: self.chk(n, pf)[0] for n, pf in (('deadsvc', dpf), ('silentsvc', lpf), ('okay', hpf), ('sick', upf))}
        self.assertEqual(sorted(got.values()), [0, 1, 2, 3]); self.assertEqual(len(set(got.values())), 4)


class States(Fixture):
    def test_healthy_idle_service_with_a_fresh_heartbeat_and_no_log_activity(self):
        pid = self.live(); pf = self.pidfile('idle', pid); self.beat('idle', pid, age=5)
        rc, out, _ = self.chk('idle', pf); self.assertEqual((rc, out.split()[0]), (0, 'HEALTHY'))

    def test_unhealthy_when_the_fresh_heartbeat_reports_a_problem(self):
        for status in ('degraded', 'failing'):
            with self.subTest(status=status):
                pid = self.live(); pf = self.pidfile('s' + status, pid); self.beat('s' + status, pid, status=status, detail='queue stuck')
                rc, out, _ = self.chk('s' + status, pf); self.assertEqual((rc, out.split()[0]), (1, 'UNHEALTHY')); self.assertIn('queue stuck', out)

    def test_a_stale_heartbeat_on_a_live_process_is_no_heartbeat_not_unhealthy_and_not_dead(self):
        pid = self.live(); pf = self.pidfile('s', pid); self.beat('s', pid, age=3600, status='failing')
        rc, out, _ = self.chk('s', pf); self.assertEqual((rc, out.split()[0]), (2, 'NO-HEARTBEAT'))

    def test_dead_process_with_no_heartbeat_ever(self):
        rc, out, _ = self.chk('gone', self.pidfile('gone', self.dead())); self.assertEqual((rc, out.split()[0]), (3, 'DEAD')); self.assertIn('no heartbeat ever recorded', out)

    def test_dead_process_a_fresh_looking_heartbeat_does_not_save_it(self):
        pid = self.dead(); pf = self.pidfile('s', pid); self.beat('s', pid, age=1)
        rc, out, _ = self.chk('s', pf); self.assertEqual((rc, out.split()[0]), (3, 'DEAD'))

    def test_a_missing_pidfile_with_a_heartbeat_on_record_is_dead_with_its_last_beat(self):
        self.beat('s', 12345, age=400)
        rc, out, _ = self.chk('s', os.path.join(self.d, 'absent.pid')); self.assertEqual((rc, out.split()[0]), (3, 'DEAD')); self.assertIn('last heartbeat 400s ago', out)

    def test_neither_pidfile_nor_heartbeat_is_unknown(self):
        rc, out, _ = self.chk('never', os.path.join(self.d, 'absent.pid')); self.assertEqual((rc, out.split()[0]), (4, 'UNKNOWN'))

    def test_a_zombie_is_dead(self):
        pid = self.zombie(); rc, out, _ = self.chk('z', self.pidfile('z', pid)); self.assertEqual((rc, out.split()[0]), (3, 'DEAD'))

    def test_a_heartbeat_from_a_previous_incarnation_does_not_count(self):
        old = self.dead(); pid = self.live(); pf = self.pidfile('s', pid); self.beat('s', old, age=1)
        rc, out, _ = self.chk('s', pf); self.assertEqual((rc, out.split()[0]), (2, 'NO-HEARTBEAT')); self.assertIn('previous incarnation', out)

    def test_a_heartbeat_from_the_future_does_not_count(self):
        pid = self.live(); pf = self.pidfile('s', pid); self.beat('s', pid, age=-7200)
        rc, out, _ = self.chk('s', pf); self.assertEqual((rc, out.split()[0]), (2, 'NO-HEARTBEAT')); self.assertIn('future', out)

    def test_corrupt_and_malformed_heartbeat_files_are_no_heartbeat(self):
        pid = self.live(); pf = self.pidfile('s', pid)
        for text in ('not json', '[]', '{"ts": "x", "pid": 1}', '{"pid": 1}', ''):
            with self.subTest(text=text):
                with open(os.path.join(self.d, 's.json'), 'w') as fh: fh.write(text)
                rc, out, _ = self.chk('s', pf); self.assertEqual((rc, out.split()[0]), (2, 'NO-HEARTBEAT'))

    def test_threshold_boundary(self):
        pid = self.live(); pf = self.pidfile('s', pid); now = time.time()
        hb.write_beat(self.d, 's', pid, now=now - 60)
        self.assertEqual(hb.check('s', pf, 60, self.d, now=now)['state'], 'HEALTHY')
        self.assertEqual(hb.check('s', pf, 60, self.d, now=now + 1)['state'], 'NO-HEARTBEAT')

    def test_all_five_states_have_distinct_exit_statuses_and_words(self):
        self.assertEqual(sorted(hb.STATES.values()), [0, 1, 2, 3, 4]); self.assertEqual(len(set(hb.STATES)), 5)

    def test_check_never_modifies_the_heartbeat(self):
        pid = self.live(); pf = self.pidfile('s', pid); self.beat('s', pid)
        p = os.path.join(self.d, 's.json'); before = (os.stat(p).st_mtime_ns, rd(p)); self.chk('s', pf)
        self.assertEqual((os.stat(p).st_mtime_ns, rd(p)), before)

    def test_json_output_carries_the_state_and_exit(self):
        pid = self.live(); pf = self.pidfile('s', pid); self.beat('s', pid)
        rc, out, _ = self.cli('check', 's', '--pidfile', pf, '--max-age', '60', '--json'); j = json.loads(out)
        self.assertEqual((rc, j['state'], j['exit'], j['process'], j['pid']), (0, 'HEALTHY', 0, 'alive', pid))


class Beat(Fixture):
    def test_beat_writes_an_atomic_record_and_increments_seq(self):
        for i in (1, 2, 3):
            self.assertEqual(self.cli('beat', 'svc', '--pid', '42')[0], 0)
            self.assertEqual(json.loads(rd(os.path.join(self.d, 'svc.json')))['seq'], i)
        self.assertEqual(sorted(os.listdir(self.d)), ['svc.json'])

    def test_beat_defaults_the_pid_to_its_parent_the_service(self):
        p = subprocess.run([sys.executable, '-c', 'import subprocess,sys,os; subprocess.run([sys.executable,"-I",%r,"beat","svc","--dir",%r]); print(os.getpid())' % (PROG, self.d)], capture_output=True, text=True)
        self.assertEqual(json.loads(rd(os.path.join(self.d, 'svc.json')))['pid'], int(p.stdout))

    def test_beat_rejects_bad_names_and_statuses(self):
        for bad in ('../x', 'a/b', '', '.hidden', 'a b'):
            with self.subTest(name=bad):
                self.assertEqual(self.cli('beat', bad)[0], 64)
        self.assertEqual(self.cli('beat', 'svc', '--status', 'great')[0], 64)

    def test_a_reader_never_sees_half_a_record(self):
        stop = time.time() + 1.5; n = 0
        w = subprocess.Popen([sys.executable, '-c', 'import sys,time; sys.path.insert(0,%r)\nimport importlib.machinery as m, importlib.util as u\ns=u.spec_from_loader("hb",m.SourceFileLoader("hb",%r)); hb=u.module_from_spec(s); s.loader.exec_module(hb)\nend=time.time()+1.5\nwhile time.time()<end: hb.write_beat(%r,"svc",1,detail="x"*150)' % (HERE, PROG, self.d)])
        self.kids.append(w)
        while time.time() < stop:
            try: json.loads(rd(os.path.join(self.d, 'svc.json'))); n += 1
            except FileNotFoundError: pass
        w.wait(10); self.assertGreater(n, 50)

    def test_detail_is_truncated(self):
        r = hb.write_beat(self.d, 's', 1, detail='x' * 5000); self.assertEqual(len(r['detail']), 200)


class CheckAll(Fixture):
    def test_one_line_per_service_worst_exit_and_comments_skipped(self):
        okpid = self.live(); self.beat('okay', okpid)
        spec = os.path.join(self.d, 'spec')
        with open(spec, 'w') as fh:
            fh.write('# services\nokay %s 60\n\ngone %s 60   # dead one\nsilent %s 60\n' % (self.pidfile('okay', okpid), self.pidfile('gone', self.dead()), self.pidfile('silent', self.live())))
        rc, out, _ = self.cli('check-all', spec); words = [l.split()[0] for l in out.splitlines()]
        self.assertEqual(words, ['HEALTHY', 'DEAD', 'NO-HEARTBEAT']); self.assertEqual(rc, 3)

    def test_all_healthy_is_zero(self):
        pid = self.live(); self.beat('okay', pid); spec = os.path.join(self.d, 'spec')
        with open(spec, 'w') as fh: fh.write('okay %s 60\n' % self.pidfile('okay', pid))
        self.assertEqual(self.cli('check-all', spec)[0], 0)

    def test_a_bad_spec_line_is_a_usage_error(self):
        spec = os.path.join(self.d, 'spec')
        with open(spec, 'w') as fh: fh.write('only-two-fields x\n')
        self.assertEqual(self.cli('check-all', spec)[0], 64)


class Usage(Fixture):
    def test_usage_errors_exit_64_never_a_state_code(self):
        for args in (['check'], ['check', 'x'], ['check', 'x', '--pidfile', 'p'], ['bogus'], ['check', 'x', '--pidfile', 'p', '--max-age', 'abc']):
            with self.subTest(args=args):
                self.assertEqual(self.cli(*args)[0], 64)


class NotWiredToAlerts(unittest.TestCase):
    def test_the_program_has_no_alert_mail_or_network_path(self):
        code = '\n'.join(l for l in rd(PROG).splitlines() if not l.strip().startswith('#'))
        code = re.sub(r'""".*?"""', '', code, flags=re.S)
        for needle in ('honey-alert', 'telegram', 'mailcortex', 'socket', 'urllib', 'http.client', 'smtplib', 'requests', 'subprocess', 'os.system', 'os.exec', 'rc-service'):
            self.assertNotIn(needle, code, needle)


